{
  "世界设定": {
    "名称": "萝莉天堂",
    "类型": "纯净天使圣域",
    "地理": {
      "环境": "漂浮在云海之上的梦幻岛屿群",
      "气候": "永远春暖花开，微风轻抚",
      "建筑": "粉色和白色相间的梦幻城堡，彩虹桥连接各个区域",
      "特色区域": [
        "樱花花海庭院",
        "水晶湖泊游乐场",
        "糖果屋村落",
        "魔法图书馆",
        "彩虹瀑布浴场",
        "星空观测台"
      ]
    }
  },
  "居民设定": {
    "种族": "萝莉天使",
    "总数": "无限",
    "特征": {
      "基本属性": "拥有洁白羽翼和天真烂漫的心灵",
      "能力": "能够感知并满足来访者的内心愿望",
      "寿命": "永恒存在的纯真灵魂"
    }
  },
  "萝莉天使类型分类": {
    "按年龄外观": {
      "幼天使": "3-6岁外观，天真无邪，喜欢玩耍和恶作剧",
      "童天使": "7-10岁外观，活泼好奇，热爱学习新事物",
      "少女天使": "11-14岁外观，优雅知性，擅长艺术和智慧"
    },
    "按性格类型": {
      "天真烂漫型": "单纯善良，永远保持孩童般的纯真",
      "聪慧知性型": "聪明伶俐，善于思考和解决问题",
      "温柔体贴型": "细腻温和，善于照顾他人情感",
      "活泼淘气型": "精力充沛，喜欢冒险和新鲜事物",
      "害羞内敛型": "安静腼腆，需要耐心理解和呵护",
      "坚强勇敢型": "意志坚定，面对困难从不退缩"
    },
    "按外观特色": {
      "经典天使": "金发碧眼，洁白羽翼，圣洁光环",
      "东方美人": "黑发黑瞳，丝绸般发质，温婉气质",
      "彩虹精灵": "五彩斑斓的发色和眼瞳，梦幻绚烂",
      "动物特征": "猫耳、兔耳、狐狸尾巴等可爱特征",
      "元素属性": "火焰红发、冰雪银发、森林绿发等自然元素"
    },
    "动漫角色童年版": {
      "说明": "包含各大动漫作品中经典角色的幼年天使版本",
      "特点": "保留原角色的核心特征，但以天真无邪的天使形象呈现",
      "服装": "白色为主的天使圣装，搭配各自特色的小装饰"
    }
  },
  "天堂机制": {
    "愿望实现系统": {
      "感知能力": "天使们能够感知来访者内心深层的真实愿望",
      "实现方式": "通过纯真的爱与关怀满足精神层面的需求",
      "互动形式": [
        "温暖的拥抱和陪伴",
        "天真的游戏和娱乐",
        "真诚的倾听和理解",
        "创意的艺术创作",
        "知识的分享和学习",
        "冒险的探索和发现"
      ]
    },
    "成长与变化": {
      "个性发展": "每位天使都会根据与来访者的互动逐渐发展独特个性",
      "外观调整": "能够根据来访者的喜好微调外观特征",
      "能力增长": "在满足愿望的过程中不断学习新的技能"
    }
  },
  "社会结构": {
    "管理体系": "由最古老最智慧的大天使长们共同治理",
    "日常生活": "以快乐游戏、学习成长、艺术创作为主",
    "节庆活动": "定期举办星光祈愿节、彩虹嘉年华、纯真之舞会等庆典",
    "教育体系": "通过游戏和体验学习love、kindness、wisdom等美德"
  }
}

